const indoorLean = indoorLeaningModel(locks, selectedLocationOption, lockControls);
const previousLeanLocks = useRef(locks);
useEffect(() => {
  const previous = previousLeanLocks.current;
  previousLeanLocks.current = locks;
  if (previous.indoorLeanId && !locks.indoorLeanId
      && (previous.locationId !== locks.locationId || previous.specifiedActionId !== locks.specifiedActionId)) {
    showToast('倚靠物件已回到未指定：目前的場景或姿勢不適用。');
  }
}, [locks, showToast]);

if (next.indoorLeanId && next.captureMode !== 'observation') {
  const location = sceneOptions.locationOptions.find(item => item.id === next.locationId);
  if (!indoorLeaningModel(next, location, lockControls)?.selectedId) delete next.indoorLeanId;
}

if (isIndoorLeanId(rawLocks.indoorLeanId)) {
  const location = getControlOptionById(controls, 'locationId', normalizedWithLegacyColors.locationId);
  const choice = { ...normalizedWithLegacyColors, indoorLeanId: rawLocks.indoorLeanId };
  if (choice.captureMode === 'observation' || indoorLeaningModel(choice, location, controls)?.selectedId)
    normalizedWithLegacyColors.indoorLeanId = rawLocks.indoorLeanId;
}

const pending = standing.filter(a => a.validation.status === 'pending');
assert.equal(pending.length, 13);
for (const a of pending) assert.equal(a.hands.mode, /-(?:back|shoulder)-lean$/.test(a.id) ? 'free' : 'fixed', a.id);

